import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.qXLDknWC.js";const u=JSON.parse('{"title":"CharacterVault 1.3.1","description":"","frontmatter":{},"headers":[],"relativePath":"releases/v1.3.1.md","filePath":"releases/v1.3.1.md"}'),r={name:"releases/v1.3.1.md"};function o(l,e,n,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="charactervault-1-3-1" tabindex="-1">CharacterVault 1.3.1 <a class="header-anchor" href="#charactervault-1-3-1" aria-label="Permalink to &quot;CharacterVault 1.3.1&quot;">​</a></h1><p>Provider polish: a dedicated Synthetic adapter with live quotas, a fuller OpenRouter adapter with key spend, and an API key field that no longer looks like a login.</p><p><strong>Try it:</strong> <a href="https://spaceman2408.github.io/CharacterVault" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault</a><br><strong>Docs:</strong> <a href="https://spaceman2408.github.io/CharacterVault/docs/" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault/docs/</a></p><hr><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="synthetic" tabindex="-1">Synthetic <a class="header-anchor" href="#synthetic" aria-label="Permalink to &quot;Synthetic&quot;">​</a></h3><ul><li>New <strong>Synthetic</strong> preset in <strong>Settings → AI Config</strong> (<code>https://api.synthetic.new/v1</code>)</li><li>Model list prefers <code>syn:</code> aliases (Large text, Small text, and vision variants) so you always get the latest recommended model</li><li>Embedding-only models are filtered out of the picker</li><li>Reasoning effort allowlists are seeded from the catalog when Synthetic reports them</li><li><strong>Synthetic Usage</strong> card shows live <strong>five-hour requests</strong> and <strong>weekly credits</strong> from <code>/v2/quotas</code></li><li><code>top_k</code> and <code>repetition_penalty</code> stay on the request — Synthetic lists them as supported</li></ul><p><a href="/CharacterVault/docs/configuration/ai-setup#synthetic-usage">AI Setup → Synthetic Usage</a></p><h3 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h3><ul><li>Dedicated adapter for <code>openrouter.ai</code> instead of the generic OpenAI-compat fallback</li><li>Catalog uses display names, drops non-text models, and seeds per-model reasoning efforts</li><li>Chat requests send CharacterVault app attribution headers</li><li><strong>OpenRouter Usage</strong> card reads <code>GET /api/v1/key</code> for this key’s spend (today / week / month / all time), an optional spending cap, and free-tier <code>:free</code> rate limits</li><li>A normal inference key does not return account balance — spend is for this key only</li></ul><p><a href="/CharacterVault/docs/configuration/ai-setup#openrouter-usage">AI Setup → OpenRouter Usage</a></p><h3 id="api-key-field" tabindex="-1">API key field <a class="header-anchor" href="#api-key-field" aria-label="Permalink to &quot;API key field&quot;">​</a></h3><ul><li>The key is still masked, but it is no longer <code>type=&quot;password&quot;</code></li><li><strong>Save Settings</strong> is less likely to be treated as a login, so browsers stop offering to save the key</li></ul><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><p>Client-only app. Open the hosted site or rebuild locally; no server migration.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/spaceman2408/CharacterVault</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CharacterVault</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Local data from 1.3.0 should keep working. Hard refresh if the UI looks stale after deploy.</p><hr><h2 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a></li><li><a href="/CharacterVault/docs/whats-new">What&#39;s New</a></li><li><a href="/CharacterVault/docs/changelog">Changelog</a></li></ul>`,21)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
